def normalize_bindings(apps, schema_editor):
    Binding = apps.get_model('club', 'PlatformBinding')
    for binding in Binding.objects.using(schema_editor.connection.alias).all().iterator():
        binding.normalized_account = binding.account.strip().casefold()
        binding.sync_state = {'version': 2, 'phase': 'done', 'complete': False}
        binding.save(update_fields=['normalized_account', 'sync_state'])


def seed_records(apps, schema_editor):
    Baseline = apps.get_model('club', 'PlatformSolvedBaseline')
    Record = apps.get_model('club', 'PlatformSolvedRecord')
    alias = schema_editor.connection.alias
    for base in Baseline.objects.using(alias).all().iterator():
        rows = []
        for key in set(base.problem_ids) | set(base.dated_problems):
            try:
                day = date.fromisoformat(base.dated_problems[key]) if key in base.dated_problems else None
            except (ValueError, TypeError):
                day = None
            rows.append(Record(binding_id=base.binding_id, problem_key=key.lower(), solved_on=day))
        Record.objects.using(alias).bulk_create(rows, ignore_conflicts=True, batch_size=500)


